command:
// Test-database fixture cleanup (Director: test fixtures are handled directly by the reviewer).
// Target: TEST database only, restricted match role, via the project's fixture helper. Removes the single orphaned
// timed fixture left by Codex's interrupted RUN-20261015-050 and transport quota rows that have already expired.
import assert from 'node:assert/strict';
import { using, cleanup } from './apps/match-service/tests/fixtures.mjs';
const tables = ['matches', 'clocks', 'clock_events', 'command_receipts', 'journal', 'outbox', 'transport_limits'];
const counts = () => using('match', async c => { const o = {}; for (const t of tables) o[t] = (await c.query('SELECT count(*)::int n FROM match.' + t)).rows[0].n; return o; });
const before = await counts();
const matches = await using('match', async c => (await c.query('SELECT match_id FROM match.matches')).rows.map(r => r.match_id));
assert.deepEqual(matches, ['clock-process-a0f171f0-6049-449e-90c4-75615c086fc9'], 'unexpected test-database matches; nothing removed');
await cleanup(matches[0]);
const expired = await using('match', async c => (await c.query('DELETE FROM match.transport_limits WHERE expires_at < now() RETURNING key_hash')).rowCount);
const after = await counts();
console.log(JSON.stringify({ target: 'test', removedMatch: matches[0], expiredQuotaRowsRemoved: expired, before, after }, null, 1));
assert.deepEqual(Object.values(after), [0, 0, 0, 0, 0, 0, 0]);
